use crate::aap::caps::state_read;

struct Node;

/// Keys tried in order in the 'subscriptions' store.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds"];

/// Parse a JSON array of strings. Returns None if the text is not one.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let chars: Vec<char> = s.trim().chars().collect();
    let mut i = 0usize;
    let skip_ws = |i: &mut usize| {
        while *i < chars.len() && chars[*i].is_whitespace() {
            *i += 1;
        }
    };
    skip_ws(&mut i);
    if i >= chars.len() || chars[i] != '[' {
        return None;
    }
    i += 1;
    let mut out = Vec::new();
    skip_ws(&mut i);
    if i < chars.len() && chars[i] == ']' {
        i += 1;
        skip_ws(&mut i);
        return if i == chars.len() { Some(out) } else { None };
    }
    loop {
        skip_ws(&mut i);
        if i >= chars.len() || chars[i] != '"' {
            return None;
        }
        i += 1;
        let mut cur = String::new();
        loop {
            if i >= chars.len() {
                return None;
            }
            let c = chars[i];
            i += 1;
            match c {
                '"' => break,
                '\\' => {
                    if i >= chars.len() {
                        return None;
                    }
                    let e = chars[i];
                    i += 1;
                    match e {
                        '"' => cur.push('"'),
                        '\\' => cur.push('\\'),
                        '/' => cur.push('/'),
                        'b' => cur.push('\u{08}'),
                        'f' => cur.push('\u{0C}'),
                        'n' => cur.push('\n'),
                        'r' => cur.push('\r'),
                        't' => cur.push('\t'),
                        'u' => {
                            if i + 4 > chars.len() {
                                return None;
                            }
                            let hex: String = chars[i..i + 4].iter().collect();
                            i += 4;
                            let code = u32::from_str_radix(&hex, 16).ok()?;
                            cur.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => return None,
                    }
                }
                _ => cur.push(c),
            }
        }
        out.push(cur);
        skip_ws(&mut i);
        if i >= chars.len() {
            return None;
        }
        match chars[i] {
            ',' => {
                i += 1;
            }
            ']' => {
                i += 1;
                skip_ws(&mut i);
                return if i == chars.len() { Some(out) } else { None };
            }
            _ => return None,
        }
    }
}

/// Parse stored subscriptions: a JSON array of strings, or one URL per line
/// (commas also accepted as separators; '#' lines are comments).
fn parse_urls(raw: &str) -> Vec<String> {
    let candidates: Vec<String> = match parse_json_string_array(raw) {
        Some(v) => v,
        None => raw
            .lines()
            .flat_map(|l| l.split(','))
            .map(|s| s.to_string())
            .collect(),
    };
    let mut out: Vec<String> = Vec::new();
    for c in candidates {
        let t = c.trim();
        if t.is_empty() || t.starts_with('#') {
            continue;
        }
        if !out.iter().any(|u| u == t) {
            out.push(t.to_string());
        }
    }
    out
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // The contract requires `urls` to be present; producing an empty list
        // would violate it, so fail the node rather than fabricate subscriptions.
        panic!("LoadSubscriptions: no subscriptions found in the 'subscriptions' store");
    }
}

export!(Node);
